def comps3(g,bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                stack=[(i,j)];cells=[]
                while stack:
                    x,y=stack.pop()
                    if (x,y) in seen or not (0<=x<h and 0<=y<w) or g[x][y]==bg: continue
                    seen.add((x,y)); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and g[nx][ny]!=bg and (nx,ny) not in seen: stack.append((nx,ny))
                out.append(cells)
    return sorted(out,key=lambda c:min(c))
